import json,sys
p=sys.argv[1]
out=[]
for i,l in enumerate(open(p)):
    try:d=json.loads(l)
    except: continue
    t=d.get('type')
    m=d.get('message',{})
    c=m.get('content') if isinstance(m,dict) else None
    if t=='user':
        if isinstance(c,str): s=c
        else:
            s=' '.join(x.get('text','') for x in (c or []) if isinstance(x,dict) and x.get('type')=='text')
        if s.strip(): out.append(f"[{i}] USER: {s}")
    elif t=='assistant' and isinstance(c,list):
        s=' '.join(x.get('text','') for x in c if isinstance(x,dict) and x.get('type')=='text')
        if s.strip(): out.append(f"[{i}] ASST: {s}")
open(sys.argv[2],'w').write('\n\n'.join(out))
EOF
